          const last = unique[unique.length - 1];
          const prev = unique[unique.length - 2];
          const d = log10Safe(last) - log10Safe(prev);
          if (!Number.isFinite(d) || d >= 0.06) break; // ~15% ratio
          unique.splice(unique.length - 2, 1);
